import{_ as a,a as r,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"C POSIX 线程：创建、互斥与退出前收拢","description":"解释pthread参数寿命、部分创建失败后的join、互斥更新和一次性run状态。","frontmatter":{"title":"C POSIX 线程：创建、互斥与退出前收拢","description":"解释pthread参数寿命、部分创建失败后的join、互斥更新和一次性run状态。","showdocs":{"topics":[{"id":"c","title":"C","link":"/topics/c/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"POSIX C：文件错误与线程收拢","summary":"解释pthread参数寿命、部分创建失败后的join、互斥更新和一次性run状态。","status":"active","related":[{"title":"C 定长分配器完整实践：为 PMR 提供存储","link":"/programming/c/plus/practice/allocator-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"C POSIX 完整实践：双文件字节统计库","link":"/programming/c/plus/practice/posix-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"C POSIX 完整实践：双文件字节统计库 · C字节统计项目的输入输出是什么至C字节统计库的完整文件怎样组织","link":"/programming/c/plus/practice/posix-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"C POSIX 完整实践：双文件字节统计库 · C字节统计项目怎样准备和构建至资料与适用边界","link":"/programming/c/plus/practice/posix-application-part-02","kind":"开发实践","scope":"general","audience":"general"},{"title":"C 定长池：布局、归还与故障边界","link":"/programming/c/allocator-contracts","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"C POSIX 文件 I/O：短读写、错误与诊断","link":"/programming/c/posix-file-io"},"next":{"text":"C POSIX 完整实践：双文件字节统计库","link":"/programming/c/plus/practice/posix-application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"C POSIX 文件 I/O：短读写、错误与诊断","link":"/programming/c/posix-file-io"},"next":{"text":"C POSIX 完整实践：双文件字节统计库","link":"/programming/c/plus/practice/posix-application"}},"headers":[],"relativePath":"programming/c/plus/subjects/posix-threads.md","filePath":"programming/c/plus/subjects/posix-threads.md"}'),i={name:"programming/c/plus/subjects/posix-threads.md"};function o(p,e,l,s,c,m){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="c-posix-线程-创建、互斥与退出前收拢" tabindex="-1">C POSIX 线程：创建、互斥与退出前收拢 <a class="header-anchor" href="#c-posix-线程-创建、互斥与退出前收拢" aria-label="Permalink to &quot;C POSIX 线程：创建、互斥与退出前收拢&quot;">​</a></h1><p>前置：C指针与对象生存期。jobs、scan和run来自<a href="/programming/c/plus/practice/posix-application#source">双文件统计库</a>的scan.c；先确认谁持有参数，再推演线程结束与销毁顺序。</p><p>用一个时序检查任务参数的生存期：主线程填好 <code>jobs[0]</code>，创建线程，工作线程读参数，主线程 <code>pthread_join</code> 返回，最后才可释放参数。若第二次创建失败，前一个线程也必须经过这条收尾路径。</p><p>专题入口：<a href="/programming/c/posix-file-io#part-1">C POSIX 文件接口：描述符、短读写与错误契约</a> · <a href="/programming/c/plus/subjects/posix-threads">C POSIX 线程：创建、互斥与退出前收拢</a> · <a href="/programming/c/plus/practice/posix-application">C POSIX 完整实践：双文件字节统计库</a> · <a href="/programming/c/posix-file-io#part-2">C POSIX 排错：系统错误、死锁与不完整输出</a></p><h2 id="lifetime" tabindex="-1">C线程参数为什么不能指向短命栈变量 <a class="header-anchor" href="#lifetime" aria-label="Permalink to &quot;C线程参数为什么不能指向短命栈变量 {#lifetime}&quot;">​</a></h2><p>pthread_create 可能在调用返回之前就开始运行新线程。必须先初始化 jobs 的 path 与 owner，再创建线程；参数对象的生存期必须覆盖线程结束。项目把 jobs 放在堆上的 scan 中，run 在返回之前 join，destroy 只允许在 run 之后同一拥有者调用。</p><p>不能在循环里把同一个局部 i 的地址交给所有线程，也不能从启动函数返回时释放它们还在使用的状态。线程调度顺序不确定，不能根据屏幕上偶尔观察到的顺序推断安全。</p><h2 id="join" tabindex="-1">C部分线程创建失败如何清理 <a class="header-anchor" href="#join" aria-label="Permalink to &quot;C部分线程创建失败如何清理 {#join}&quot;">​</a></h2><p>started 只记录成功创建的线程数。第二次创建失败时，第一次线程仍可能正在读取；run 必须对 threads[0..started) 执行 pthread_join，收拢后再返回创建错误。失败的线程ID未初始化，不能参与 join。</p><p>线程只能由本拥有者 join 一次，不能同时让另一个线程 join 或 detach。join 失败不是“线程已结束”的证据；本例把这种内部不变式破坏视为致命错误并 abort，绝不继续 free 仍可能被使用的内存。普通资源不足由创建错误返回，致命路径不是业务恢复策略。</p><h2 id="mutex" tabindex="-1">C互斥锁应该保护哪些状态 <a class="header-anchor" href="#mutex" aria-label="Permalink to &quot;C互斥锁应该保护哪些状态 {#mutex}&quot;">​</a></h2><p>两个 worker 都可能更新 total，读取、检查溢出、加法与写回必须处于同一个 pthread_mutex_lock 临界区。只锁赋值会让两线程都读到旧值；volatile 也不能让复合更新成为原子操作。每个 worker 的局部 bytes 不共享，因此读取文件时不持锁。</p><p>本例只有一把默认非稳健互斥锁，不使用递归重入或拥有者死亡恢复。lock/unlock 不应在满足这些约束的正常路径失败；不满足时中止。若改成 robust mutex，EOWNERDEAD 表示已取得锁但数据可能不一致，需要新恢复协议，不能直接沿用这里的 require_success。</p><h2 id="visibility" tabindex="-1">C主线程何时可以读取工作线程结果 <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;C主线程何时可以读取工作线程结果 {#visibility}&quot;">​</a></h2><p>join 完成后主线程再读每个 worker 的 error，不能边运行边无锁轮询。total 的并发写由 mutex 串行化，最终读取在全部 join 后；ready 只由主线程在全部成功后设为1。即使另一个线程已成功累加，任一失败也不发布报告。</p><p>attempted 在启动前置位，使 run 是一次性状态机：created → attempted → ready 或 failed。失败不支持重试，避免重复累计；第二次调用返回 EALREADY。此句柄不允许外部并发调用，内部有锁不代表所有公开操作都线程安全。</p><h2 id="exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;独立练习 {#exercise}&quot;">​</a></h2><p>第二次 create 失败时列出可以 join 的ID。若把 join 移到 mutex 临界区内部，会怎样？失败后为什么拒绝第二次 run？</p><details class="details custom-block"><summary>参考解答与检查条件</summary><p>只能join第一次成功创建的ID。worker结束前要取同一锁，持锁join会互等。一次性状态避免把第一次部分累计混进第二次结果；失败也先收拢线程再返回。</p></details><h2 id="sources" tabindex="-1">资料与适用边界 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;资料与适用边界 {#sources}&quot;">​</a></h2><p>2026-10-17 核对 <a href="https://man7.org/linux/man-pages/man2/read.2.html" target="_blank" rel="noopener noreferrer">Linux read 手册</a>、<a href="https://man7.org/linux/man-pages/man2/write.2.html" target="_blank" rel="noopener noreferrer">write 手册</a>、<a href="https://man7.org/linux/man-pages/man2/close.2.html" target="_blank" rel="noopener noreferrer">close 的平台差异</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_create.3.html" target="_blank" rel="noopener noreferrer">pthread_create</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_join.3.html" target="_blank" rel="noopener noreferrer">pthread_join</a> 与 <a href="https://man7.org/linux/man-pages/man3/pthread_mutex_lock.3p.html" target="_blank" rel="noopener noreferrer">POSIX mutex 规范镜像</a>。Linux 手册中的实现差异不直接推广为 macOS 实测结果。工程由 <a href="https://cmake.org/cmake/help/v3.20/module/FindThreads.html" target="_blank" rel="noopener noreferrer">CMake FindThreads</a> 提供线程目标，构建期会检查平台需要哪些编译和链接设置。</p><p>C++ 链接与拥有关系参照 <a href="https://en.cppreference.com/w/cpp/language/language_linkage.html" target="_blank" rel="noopener noreferrer">cppreference language linkage</a>、<a href="https://en.cppreference.com/w/cpp/memory/unique_ptr.html" target="_blank" rel="noopener noreferrer">unique_ptr</a>；中文核对 <a href="https://learn.microsoft.com/zh-cn/cpp/cpp/extern-cpp?view=msvc-170" target="_blank" rel="noopener noreferrer">Microsoft extern 说明</a>，仅引用语言链接概念，不套用其 Windows 编译开关。文章采用独立组织的边界与失败推演，外链用于溯源，必要答案已在正文。</p>',22)])])}const u=a(i,[["render",o]]);export{d as __pageData,u as default};
